from math import isqrt

# else belongs to the loop: it runs if the loop was never broken.
def is_prime(n):
    if n < 2:
        return False
    for d in range(2, isqrt(n) + 1):
        if n % d == 0:
            break                 # found a divisor: skip the else
    else:
        return True               # no break happened: no divisor found
    return False

print([n for n in range(2, 30) if is_prime(n)])

# Empty iterable: the body never runs, but else still runs.
for x in []:
    print("never")
else:
    print("else ran on an empty loop")

# The same search with any(), often easier to read.
def is_prime_any(n):
    return n > 1 and not any(n % d == 0 for d in range(2, isqrt(n) + 1))
print("agree on 2..99:", all(is_prime(n) == is_prime_any(n) for n in range(100)))

# else also runs for a while loop that ends by its condition.
i = 0
while i < 3:
    i += 1
else:
    print("while ended normally, i =", i)

