# A toy hash table with chaining shows why lookups are fast on average.
class ToyTable:
    def __init__(self, size=8):
        self.buckets = [[] for _ in range(size)]
    def put(self, key, value):
        b = self.buckets[hash(key) % len(self.buckets)]   # hash picks a bucket
        for pair in b:
            if pair[0] == key:
                pair[1] = value
                return
        b.append([key, value])
    def get(self, key):
        b = self.buckets[hash(key) % len(self.buckets)]   # look in one bucket only
        for k, v in b:
            if k == key:
                return v
        raise KeyError(key)

t = ToyTable()
for n in range(20):
    t.put(n, n * n)               # int hashes are stable, so output is stable
print("get(7) =", t.get(7))
print("bucket sizes:", [len(b) for b in t.buckets])

# Keys that all collide make lookups O(n).
class Bad:
    def __hash__(self): return 1
    def __eq__(self, other): return self is other
bad = {Bad(): i for i in range(5)}
print("5 colliding keys stored:", len(bad))

